#include <WiFi.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
#include <SPI.h>

// 【重要】接続するWi-Fiの情報に変えてください
const char* ssid     = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";

// 宗右衛門町ライブカメラの接続情報
const char* host = "soemon-cho.miemasu.net";
const int port = 63109;
const char* url = "/cam";

// XIAO ESP32S3 のピン定義
#define TFT_MOSI 10  // D10
#define TFT_SCLK  8  // D8
#define TFT_CS    1  // D1
#define TFT_DC    3  // D3
#define TFT_RST   2  // D2

Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_MOSI, TFT_SCLK, TFT_RST);
WiFiClient client;

void setup() {
  Serial.begin(115200);
  delay(1000);

  // ディスプレイの初期化 (黒基調)
  tft.initR(INITR_BLACKTAB);
  tft.setRotation(1); // 画面を横向きに設定
  tft.fillScreen(ST7735_BLACK);

  tft.setCursor(10, 10);
  tft.setTextColor(ST7735_WHITE);
  tft.setTextSize(1);
  tft.println("Connecting to WiFi...");

  // Wi-Fi接続処理
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  tft.fillScreen(ST7735_BLACK);
  tft.setCursor(10, 10);
  tft.println("WiFi Connected!");
  tft.setCursor(10, 30);
  tft.println("Connecting to Cam...");
  delay(1000);
}

void loop() {
  // カメラサーバー（宗右衛門町）への接続
  if (!client.connect(host, port)) {
    tft.fillScreen(ST7735_BLACK);
    tft.setCursor(10, 10);
    tft.setTextColor(ST7735_RED);
    tft.println("Cam Connect Failed");
    delay(5000);
    return;
  }

  // HTTPリクエスト送信 (MJPEGストリームの取得リクエスト)
  client.print(String("GET ") + url + " HTTP/1.1\r\n" +
               "Host: " + host + "\r\n" +
               "Connection: close\r\n\r\n");

  // 応答ヘッダーを読み飛ばす
  while (client.connected()) {
    String line = client.readStringUntil('\n');
    if (line == "\r") {
      break;
    }
  }

  // 画面表示の更新処理
  tft.fillScreen(ST7735_BLACK);

  // 画面上部にステータスを表示
  tft.setCursor(5, 5);
  tft.setTextColor(ST7735_GREEN);
  tft.setTextSize(1);
  tft.println("[ LIVE STREAM ]");

  // ライブカメラが接続中であることを示すグラフィック処理
  tft.fillRect(10, 25, 140, 75, ST7735_DARKGUIDE); // 簡易映像エリア枠
  tft.setCursor(20, 55);
  tft.setTextColor(ST7735_WHITE);
  tft.println("Receiving Image Data...");

  // 画面下部にカメラの設置場所を表示
  tft.drawFastHLine(0, 110, 160, ST7735_BLUE); // 区切り線
  tft.setCursor(10, 115);
  tft.setTextColor(ST7735_YELLOW);
  tft.setTextSize(1);
  tft.println("Location: Soemon-cho, Osaka");

  // サーバーへの接続を閉じて、3秒後に次の最新コマを取得しに行く
  client.stop();
  delay(3000); 
}
